protected void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();

    // Setup vend price journal

    datatype.parmDatatypeId(extendedTypeNum(GUPVendPriceJournalNum));
    datatype.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPVendPriceJournalNum_NumberSeqHelp"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardFetchAheadQty(10);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmWizardHighest(999999);
    datatype.parmSortField(1);

    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);

    /* Setup Price term agreement */

    datatype.parmDatatypeId(extendedTypeNum(GUPAgreementId));
    datatype.parmReferenceLabel(literalStr("@GlobalUnifiedPricing:GUPAgreementId"));
    datatype.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPPriceTermJournalTable_NumSeqHelp"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    datatype.parmSortField(2);

    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);

    /* Setup Margin component price adjustment */

    datatype.parmDatatypeId(extendedTypeNum(GUPMarginComponentAdjustmentId));
    datatype.parmReferenceLabel(literalStr("@GlobalUnifiedPricing:GUPAdjustmentId"));
    datatype.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPAdjustmentId_NumSeqHelp"));
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    datatype.parmSortField(3);

    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);

    // Offer discount
    dataType.parmDatatypeId(extendedTypeNum(RetailDiscountOfferId));
    dataType.parmReferenceHelp(literalStr("@RET4089"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(4);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

    // Mix and match disocunt
    dataType.parmDatatypeId(extendedTypeNum(RetailMixAndMatchId));
    dataType.parmReferenceHelp(literalStr("@RET4090"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(5);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

    // Multibuy discount
    dataType.parmDatatypeId(extendedTypeNum(RetailMultibuyDiscountId));
    dataType.parmReferenceHelp(literalStr("@RET4091"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(6);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

    // Threshold discount
    dataType.parmDatatypeId(extendedTypeNum(RetailThresholdDiscountId));
    dataType.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPThresholdDiscountId_NumSeqHelp"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(7);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

    // discount claim
    datatype.parmDatatypeId(extendedTypeNum(GUPDiscountClaimId));
    datatype.parmReferenceLabel(literalStr("@GlobalUnifiedPricing:GUPDiscountClaim_FormCaption"));
    datatype.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPDiscountClaim_NumSeqHelp"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(8);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

    // Free item discount
    dataType.parmDatatypeId(extendedTypeNum(GUPFreeItemDiscountId));
    datatype.parmReferenceLabel(literalStr("@GlobalUnifiedPricing:GUPFreeItemDiscount_FormCaption"));
    dataType.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPFreeItemDiscountId_NumSeqHelp"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(9);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

    // discount claim journal invoice number
    datatype.parmDatatypeId(extendedTypeNum(GUPDiscountVendorClaimJournalInvoice));
    datatype.parmReferenceLabel(literalStr("@GlobalUnifiedPricing:GUPDiscountClaimJournalInv_FormCaption"));
    datatype.parmReferenceHelp(literalStr("@GlobalUnifiedPricing:GUPDiscountClaimJournalInv_NumSeqHelp"));
    dataType.parmWizardIsContinuous(false);
    dataType.parmWizardIsManual(NoYes::No);
    dataType.parmWizardIsChangeDownAllowed(NoYes::No);
    dataType.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmIsGroupEnabled(NoYes::Yes);
    dataType.parmSortField(10);

    dataType.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(dataType);

}

[SubscribesTo(classstr(NumberSeqGlobal),delegatestr(NumberSeqGlobal, buildModulesMapDelegate))]
public static void buildModulesMapSubsciber(Map numberSeqModuleNamesMap)
{
    NumberSeqGlobal::addModuleToMap(classnum(GUPNumberSeqModule), numberSeqModuleNamesMap);
}
